using PCHIPInterpolation

# The 85 geometric time nodes [s] on which the ANN reproduces the transfer function. They are
# fixed by the training procedure (Pasquier et al., 2018); the last node (604800 s = 7 days)
# marks the short-term validity horizon.
const _ST_NODES = [
    15, 30, 45, 60, 75, 90, 105, 120, 135, 150, 180, 195, 225, 240, 270, 300, 345, 390, 420,
    480, 540, 600, 660, 750, 840, 930, 1035, 1170, 1305, 1470, 1620, 1830, 2040, 2280, 2535,
    2865, 3180, 3570, 3975, 4470, 4965, 5580, 6210, 6975, 7755, 8730, 9690, 10905, 12120, 13635,
    15150, 17040, 18930, 21300, 23670, 26625, 29580, 33285, 36975, 41595, 46215, 52005, 57780,
    64995, 72225, 81255, 90285, 101565, 112845, 126960, 141060, 158685, 176325, 198360, 220410,
    247950, 275505, 309945, 344385, 387435, 430485, 484290, 538095, 571455, 604800
]

"""
    short_term_response(t, rb, ri, ro, H, s, V̇, ks, Cs, kg, Cg, kp, Cp, Cf; clamp=true)

Short-term transfer function of the borehole-**outlet** fluid temperature (`T_out`, i.e. the
entering water temperature on the heat-pump source side), constructed with the artificial
neural network of Pasquier, Zarrella & Labib (2018). The network emulates the 2.5D thermal
resistance and capacity model and directly yields a dimensionless transfer function for a unit
temperature step (ΔT = 1 °C) between the borehole inlet and outlet, so it embeds the borehole
geometry, thermal capacity and vertical fluid advection. The mean absolute error with respect to
the reference model is about 2e-4, with a maximum absolute error near 8e-3. The function is only
valid over the 7-day short-term horizon and within the ANN training ranges (see below); use
`outlet_transfer_function` in GroundHeatExchanger.jl to join it to a long-term ground model for the
full minutes-to-decadesresponse.
# Arguments
    - `t`: Time value or vector [s] (maximum of 7 days)
    - `rb`: Borehole radius [m]
    - `ri`: Inner pipe radius [m]
    - `ro`: Outer pipe radius [m]
    - `H`: Borehole length [m]
    - `s`: Shank spacing (distance between the two legs of the U-tube) [m]
    - `V̇`: Fluid flow rate [m³/s]
    - `ks`: Ground thermal conductivity [W/mK]
    - `Cs`: Ground volumetric heat capacity [J/Km³]
    - `kg`: Grout thermal conductivity [W/mK]
    - `Cg`: Grout volumetric heat capacity [J/Km³]
    - `kp`: Pipe thermal conductivity [W/mK]
    - `Cp`: Pipe volumetric heat capacity [J/Km³]
    - `Cf`: Fluid volumetric heat capacity [J/Km³]
    - `clamp`: out-of-range handling, `true` (default) clamps inputs to the training bounds
        and emits a `@warn`; `false` emits an `@error` and throws an `ArgumentError`.
# Output
    - `t`: Evaluation time(s) [s] (the last value clamped to the horizon when `clamp` is `true`)
    - `g`: Dimensionless short-term outlet transfer function at `t` [-]
# Validity ranges (ANN training bounds)
    - t: 15 s – 7 days (horizon applied to the last value)
    - rb: (2ro+2mm)–0.1 m
    - ri: 0.017 m
    - ro: 0.022 m
    - H: 110–200 m
    - s: 2(0.02(rb-2ro)+ro) – 2(0.98(rb-2ro)+ro) m (twice the half-shank spacing)
    - V̇: 3.33e-4–5.0e-4 m³/s
    - ks: 0.5–4 W/mK
    - Cs: 1.7–2.6 MJ/m³K
    - kg: 0.5–3 W/mK
    - Cg: 1.7–2.6 MJ/m³K
    - kp: 0.4 W/mK
    - Cp: 1.9 MJ/m³K
    - Cf: 4.2 MJ/m³K
# Reference
    - Pasquier, P., Zarrella, A., & Labib, R. (2018). Application of artificial neural networks
        to near-instant construction of short-term g-functions. Applied Thermal Engineering,
        143, 910–921. https://doi.org/10.1016/j.applthermaleng.2018.07.137
"""
function short_term_response(t, rb, ri, ro, H, s, V̇, ks, Cs, kg, Cg, kp, Cp, Cf;
    clamp::Bool = true)

    # Native ANN transfer function on the 85 fixed nodes
    _, g_nodes = short_term_nodes(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s;
        clamp = clamp)

    # Validate the requested time(s); only the horizon (last value) is bounded by the ANN.
    t = _validate_time(t; clamp = clamp)

    # Shape-preserving (PCHIP) interpolation onto the requested time(s).
    itp = Interpolator(_ST_NODES, g_nodes)
    g = itp.(t)

    return t, g
end

"""
    short_term_nodes(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp=true)

Evaluate the ANN on its 85 fixed native time nodes, returning `(ts, g)` where `ts` are the node
times [s] (geometric, last node = 604800 s = 7-day horizon) and `g` is the raw short-term
transfer function on those nodes — no interpolation and no time validation, unlike
`short_term_response`. This is the low-level building block: `short_term_response` adds PCHIP
interpolation onto arbitrary `t`, and the short-/long-term join `outlet_transfer_function`
(GroundHeatExchanger.jl) consumes the raw nodes directly (it splices at `ts[end]` and does its own
interpolation). Inverts the training transformation `y = ln(t̃ / (g + 1))`. See
`short_term_response` for the argument list and ANN validity ranges.
"""
function short_term_nodes(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp::Bool = true)
    p = _input_validation(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp = clamp)
    g = 1 ./ (exp.(_ann_forward(p)) ./ _ST_NODES) .- 1
    g[g.<0] .= 0
    return _ST_NODES, g
end

"""
    _input_validation(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp=true)

Check the 13 physical inputs against the ANN training ranges. When `clamp` is `true`,
out-of-range values are `@warn`ed and clamped to the nearest bound; when `false`, an `@error`
is emitted and an `ArgumentError` is thrown. Returns the 8-element parameter vector
`[ks, Cs, kg, Cg, rb, H, V̇, D]` consumed by the network, where the half-shank spacing
`D = s / 2` is derived from the shank spacing `s`.
"""
function _input_validation(ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s; clamp::Bool = true)

    # Lower/upper bound of every physical parameter (see the validity ranges in the docstring
    # of `short_term_response`).
    p_limit = [
        0.5                 4;                 # ks
        1.7e6               2.6e6;             # Cs
        0.5                 3;                 # kg
        1.7e6               2.6e6;             # Cg
        0.4                 0.4;               # kp
        1.9e6               1.9e6;             # Cp
        4.2e6               4.2e6;             # Cf
        0.017               0.017;             # ri
        0.022               0.022;             # ro
        2 * ro + 2e-3       0.1;               # rb
        110                 200;               # H
        3.33e-4             5.0e-4;            # V̇
        2 * (0.02 * (rb - 2 * ro) + ro)   2 * (0.98 * (rb - 2 * ro) + ro)   # s (= 2·half-shank)
    ]

    params = [ks, Cs, kg, Cg, kp, Cp, Cf, ri, ro, rb, H, V̇, s]
    p_names = ["ks", "Cs", "kg", "Cg", "kp", "Cp", "Cf", "ri", "ro", "rb", "H", "V̇", "s"]
    p_units = ["W/mK", "J/Km³", "W/mK", "J/Km³", "W/mK", "J/Km³", "J/Km³", "m", "m", "m", "m",
        "m³/s", "m"]

    for i in eachindex(params)
        lo, hi = p_limit[i, 1], p_limit[i, 2]
        if params[i] < lo || params[i] > hi
            bound = params[i] < lo ? lo : hi
            msg = "Parameter $(p_names[i]) = $(params[i]) $(p_units[i]) is outside the ANN " *
                  "training range [$lo, $hi] $(p_units[i])"
            if clamp
                @warn "$msg — clamped to $bound $(p_units[i])"
                params[i] = bound
            else
                @error msg
                throw(ArgumentError(msg))
            end
        end
    end

    # The 8 parameters fed to the network: ks, Cs, kg, Cg, rb, H, V̇, D. The ANN was trained on
    # the half-shank spacing D, so the shank spacing s (params[13]) is converted back with D = s/2.
    return [params[1], params[2], params[3], params[4], params[10], params[11], params[12],
        params[13] / 2]
end

"""
    _validate_time(t; clamp=true)

Check the requested evaluation time(s) `t` (scalar or vector) against the ANN short-term
horizon (15 s – 7 days), applying the same `clamp` policy as `_input_validation`. Only the last
(largest) value is bounded; the returned `t` has that value clamped when `clamp` is `true`
(a copy is made for vectors so the caller's array is left untouched).
"""
function _validate_time(t; clamp::Bool = true)
    lo, hi = 15, 7 * 24 * 3600
    tlast = last(t)
    (lo <= tlast <= hi) && return t

    bound = tlast < lo ? lo : hi
    msg = "Final evaluation time t = $tlast s is outside the short-term range [$lo, $hi] s"
    if !clamp
        @error msg
        throw(ArgumentError(msg))
    end
    @warn "$msg — clamped to $bound s"
    if t isa AbstractVector
        t = float.(t)
        t[end] = bound
        return t
    else
        return bound
    end
end

"""
    _ann_forward(x1)

Forward pass of the trained multilayer perceptron: two tanh hidden layers and a linear output
layer, with min–max scaling on the input and inverse scaling on the output. Maps the
8-parameter vector `x1 = [ks, Cs, kg, Cg, rb, H, V̇, D]` to the 85 transformed transfer-function
values. Ported from the MATLAB Neural Network Toolbox `genFunction` output.
"""
function _ann_forward(x1)
    # Input scaling
    xp1 = _mapminmax_apply(x1, _input_scaler)
    # Hidden layer 1
    a1 = tanh.(b1 + IW1_1 * xp1)
    # Hidden layer 2
    a2 = tanh.(b2 + LW2_1 * a1)
    # Output layer (linear)
    a3 = b3 + LW3_2 * a2
    # Output inverse scaling
    y1 = _mapminmax_reverse(a3, _output_scaler)
    return y1
end

"""
    _mapminmax_apply(x, scaler)

Forward min–max scaling (MATLAB `mapminmax_apply`): `y = (x - xoffset) * gain + ymin`. First
step of the network simulation.
"""
function _mapminmax_apply(x, scaler)
    y = x .- scaler.xoffset
    y .*= scaler.gain
    y .+= scaler.ymin
    return y
end

"""
    _mapminmax_reverse(y, scaler)

Inverse min–max scaling (MATLAB `mapminmax_reverse`): `x = (y - ymin) / gain + xoffset`. Last
step of the network simulation.
"""
function _mapminmax_reverse(y, scaler)
    x = y .- scaler.ymin
    x ./= scaler.gain
    x .+= scaler.xoffset
    return x
end

# Min–max scaler holding the offset, gain and target minimum used to normalise the network
# input and de-normalise its output.
struct _MinMaxScaler
    xoffset::Vector{Float64}
    gain::Vector{Float64}
    ymin::Int8
end

